-- Ascent ALM - initial Supabase schema. GENERATED by scripts/gen-schema.py from its table list;
-- edit the generator (and scripts/schema-header.sql / schema-footer.sql), not this file.
--
-- Shape: every table holds the application's own record in `data jsonb`, keyed by its id, with the
-- columns the app filters on generated from that record - so the database stores exactly what the
-- app saves, and row-level security can filter on affiliate, status and kind without the client
-- having to keep two copies in step.
--
-- Security: every table has row-level security. A signed-in user is mapped to their app_users row
-- (auth_user_id), whose role's permission list (roles.data->'permissions') decides what they may
-- read and write, and whose affiliate scope decides which affiliates' rows they see.

create schema if not exists app;

-- ─── Helpers ────────────────────────────────────────────────────────────────

create or replace function app.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- app_users and roles are created here (ahead of the generated tables) because the permission
-- helpers below reference them.
create table if not exists public.roles (
  code text primary key,
  data jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.app_users (
  id text primary key,
  data jsonb not null,
  auth_user_id uuid unique references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  email text generated always as (lower(data->>'email')) stored,
  role text generated always as ((data->>'role')) stored,
  affiliate_code text generated always as ((data->>'affiliateCode')) stored
);
create unique index if not exists app_users_email_key on public.app_users (email);

-- The signed-in user's own app_users record (null when signed out or not provisioned).
create or replace function app.me() returns jsonb
language sql stable security definer set search_path = public, app as $$
  select u.data from public.app_users u
  where u.auth_user_id = auth.uid() and coalesce((u.data->>'isActive')::boolean, true)
$$;

create or replace function app.has_perm(perm text) returns boolean
language sql stable security definer set search_path = public, app as $$
  select coalesce(
    (select r.data->'permissions' ? perm
       from public.roles r
      where r.code = app.me()->>'role'),
    false)
$$;

create or replace function app.has_any_perm(perms text[]) returns boolean
language sql stable security definer set search_path = public, app as $$
  select coalesce(
    (select r.data->'permissions' ?| perms
       from public.roles r
      where r.code = app.me()->>'role'),
    false)
$$;

-- Group-wide users (affiliateCode GROUP, or group.manage) see every affiliate; anyone else sees their
-- own affiliate plus Group-level rows (no affiliate, or GROUP).
create or replace function app.affiliate_ok(code text) returns boolean
language sql stable security definer set search_path = public, app as $$
  select code is null
      or code = 'GROUP'
      or app.me()->>'affiliateCode' = 'GROUP'
      or app.has_perm('group.manage')
      or code = app.me()->>'affiliateCode'
$$;

grant usage on schema app to authenticated, anon;
grant execute on all functions in schema app to authenticated;

-- ─── Tables ─────────────────────────────────────────────────────────────────

-- affiliates
create table if not exists public.affiliates (
  code text primary key,
  data jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  status text generated always as ((data->>'status')) stored,
  region text generated always as ((data->>'region')) stored,
  functional_currency text generated always as ((data->>'functionalCurrency')) stored
);
create index if not exists affiliates_status_idx on public.affiliates (status);
create index if not exists affiliates_region_idx on public.affiliates (region);
create index if not exists affiliates_functional_currency_idx on public.affiliates (functional_currency);
alter table public.affiliates add constraint affiliates_id_matches_data check (data->>'code' = code);
create trigger affiliates_touch before update on public.affiliates for each row execute function app.touch_updated_at();
alter table public.affiliates enable row level security;
create policy affiliates_read on public.affiliates for select to authenticated using (app.has_perm('dashboard.view') and app.affiliate_ok(code));
create policy affiliates_insert on public.affiliates for insert to authenticated with check (app.has_any_perm(array['group.manage']) and app.affiliate_ok(code));
create policy affiliates_update on public.affiliates for update to authenticated using (app.has_any_perm(array['group.manage']) and app.affiliate_ok(code)) with check (app.has_any_perm(array['group.manage']) and app.affiliate_ok(code));
create policy affiliates_delete on public.affiliates for delete to authenticated using (app.has_any_perm(array['group.manage']) and app.affiliate_ok(code));

